from __future__ import annotations

import json

import pytest

from llm_router import (
    LLMRouter,
    Model,
    Provider,
    RouterProfile,
    get_config,
    install_config,
)
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.tool_failure import (
    openai_tool_call_response,
)
from tests.llm_router.support.workers.worker_patches import (
    install_fast_worker_runtime_config,
    patched_openai_sdk,
)

pytestmark = pytest.mark.verification_kind("unit")


class AnswerSchema:
    """Holder whose class namespace is a read-only mapping proxy."""

    __slots__ = ()
    type = "object"
    title = "Answer"
    properties = {"answer": {"type": "string", "minLength": 2}}  # noqa: RUF012
    required = ["answer"]  # noqa: RUF012


def scripted(body: bytes) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers={"Content-Type": "application/json"},
        body=body,
    )


@pytest.mark.verifies("REQ_STRUCTURED_SCHEMA_CONTRACT[revision==2]")
def test_structured_schema_contract(
    monkeypatch: pytest.MonkeyPatch,
    request: pytest.FixtureRequest,
) -> None:
    value = "local-openrouter-value"
    monkeypatch.setenv("OPENROUTER_API_KEY_1", value)
    original = get_config()
    request.addfinalizer(lambda: install_config(original))
    install_fast_worker_runtime_config(structured_output_max_attempts=2)

    path = openai_chat_path()
    count_rule: dict[str, object] = {"type": "integer", "minimum": 1}
    stock_schema: dict[str, object] = {
        "title": "StockCount",
        "type": "object",
        "properties": {"count": count_rule},
        "required": ["count"],
    }

    def lookup_stock(*, sku: str) -> dict[str, str]:
        count_rule["type"] = "string"
        return {"sku": sku, "status": "in-stock"}

    routes = {
        ("POST", path): [
            scripted(openai_success_response(text=json.dumps({"count": 1}))),
            scripted(openai_success_response(text=json.dumps({"count": 2}))),
            scripted(openai_success_response(text=json.dumps({"answer": "ok"}))),
            scripted(
                openai_tool_call_response(
                    tool_name="lookup_stock",
                    args={"sku": "SKU-1042"},
                )
            ),
            scripted(openai_success_response(text=json.dumps({"count": "seven"}))),
            scripted(openai_success_response(text=json.dumps({"count": 7}))),
        ]
    }

    properties = {"count": {"type": "integer", "minimum": 0}}
    with_id: dict[str, object] = {
        "$id": "https://example.com/ticket_summary",
        "type": "object",
        "properties": properties,
    }
    neither: dict[str, object] = {"type": "object", "properties": properties}

    router = LLMRouter(
        RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
        temperature=0.0,
        seed=3,
    )

    with (
        ScriptedHTTPServer(port=0, routes=routes) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        with pytest.raises(
            TypeError,
            match=r"^response_schema must be a Pydantic model type"
            r" or JSON schema mapping\.$",
        ):
            router.query("report", response_schema="not a schema")

        router.query("Summarize tickets.", response_schema=with_id)
        router.query("Count tickets.", response_schema=neither)

        requests_iter = iter(server.recorded_requests("POST", path))
        with_id_body = json.loads(next(requests_iter).body)
        neither_body = json.loads(next(requests_iter).body)
        assert (
            with_id_body["response_format"]["json_schema"]["name"]
            == "https://example.com/ticket_summary"
        )
        assert (
            neither_body["response_format"]["json_schema"]["name"]
            == "structured_response"
        )

        proxy_response = router.query(
            "Answer briefly.",
            response_schema=AnswerSchema.__dict__,
        )
        assert proxy_response.data["parsed"] == {"answer": "ok"}

        stock_response = router.query(
            "How many units of SKU-1042 are in stock?",
            tools=[lookup_stock],
            response_schema=stock_schema,
        )
        assert count_rule["type"] == "string"
        assert stock_response.data["parsed"] == {"count": 7}
        assert server.request_count("POST", path) == 6
        assert len(stock_response.tool_trace) == 1
